package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LevenshteinDetailedDistance_ESTest_test17 extends LevenshteinDetailedDistance_ESTest_scaffolding {

    /**
     * Verifies the detailed edit operations when transforming one sequence into
     * another that is longer but shares some characters.
     *
     * <p>The "left" sequence has 7 characters: a single 'S' at index 3 and NUL
     * ('�') elsewhere. The "right" sequence has 8 characters: 'S', 'f' and
     * 'S' at indices 1, 3 and 5 and NUL elsewhere. Converting left into right
     * requires no deletions and exactly three substitutions.</p>
     */
    @Test(timeout = 4000)
    public void testApplyReportsThreeSubstitutionsAndNoDeletions() throws Throwable {
        LevenshteinDetailedDistance distance = new LevenshteinDetailedDistance();

        // left:  "\0\0\0S\0\0\0"  (length 7)
        char[] leftChars = new char[7];
        leftChars[3] = 'S';

        // right: "\0S\0f\0S\0\0"  (length 8)
        char[] rightChars = new char[8];
        rightChars[1] = 'S';
        rightChars[3] = 'f';
        rightChars[5] = 'S';

        CharBuffer left = CharBuffer.wrap(leftChars);
        CharBuffer right = CharBuffer.wrap(rightChars);

        LevenshteinResults results = distance.apply((CharSequence) left, (CharSequence) right);

        assertEquals(0, (int) results.getDeleteCount());
        assertEquals(3, (int) results.getSubstituteCount());
    }
}
